    #[test]
    fn single_adult_idle_cat_consumes_spoils_and_persists_tick_and_seed() {
        let mut world = WorldState {
            world_seed: 123,
            colonies: vec![ColonyRuntime {
                id: "colony-1".to_owned(),
                name: "MossClan".to_owned(),
                resources: Resources {
                    food: 100.0,
                    water: 100.0,
                    herbs: 16.0,
                    catnip: 0.0,
                    grain: 0.0,
                    flour: 0.0,
                    materials: 0.0,
                    refined: 0.0,
                    weapons: 0.0,
                    armor: 0.0,
                    planks: 0.0,
                    logs: 0.0,
                    lumber: 0.0,
                    blocks: 0.0,
                    tools: 0.0,
                    fibre: 0.0,
                    hide: 0.0,
                    cloth: 0.0,
                    leather: 0.0,
                    ore: 0.0,
                    metal: 0.0,
                    blessings: 0.0,
                },
                cats: vec![adult_idle_cat("cat-1", "colony-1")],
                last_tick: 1_000,
                test_rng_seed: Some(12_345),
                ..ColonyRuntime::default()
            }],
        };

        let mut twin = world.clone();
        let reports = world_tick(&mut world, 61_000);
        assert_eq!(reports, world_tick(&mut twin, 61_000));

        assert_eq!(
            reports,
            vec![TickReport {
                colony_id: "colony-1".to_owned(),
                skipped: false,
                reset_reason: None,
            }]
        );

        let colony = &world.colonies[0];
        let consumption = consumption_for_tick(1.0, 60.0, idle_engine::UpgradeLevels::default());
        let expected_food = apply_food_spoilage_after_consumption(
            100.0,
            consumption.food_use,
            BASE_CAPACITY.food,
            60.0,
        );
        let expected_water = 100.0 - consumption.water_use;

        assert_eq!(colony.resources.food.to_bits(), expected_food.to_bits());
        assert_eq!(colony.resources.water.to_bits(), expected_water.to_bits());
        assert_eq!(colony.resources.herbs, 16.0);
        assert_eq!(colony.status, ColonyStatus::Thriving);
        assert_eq!(colony.last_tick, 61_000);
        assert_eq!(colony.test_rng_seed, twin.colonies[0].test_rng_seed);
        let expected_age: f64 = 24.0 + 60.0 / 3600.0;
        assert_eq!(colony.cats[0].age_hours.to_bits(), expected_age.to_bits());
        assert_eq!(colony.cats[0].death_time, None);
    }

    #[test]
    fn leader_assigns_water_fetchers_over_hunts_when_water_projection_is_worse() {
        let mut cats = vec![
            adult_idle_cat("leader", "colony-1"),
            adult_idle_cat("hunter", "colony-1"),
            adult_idle_cat("builder", "colony-1"),
        ];
        cats[0].stats.leadership = 80.0;
        cats[1].stats.hunting = 90.0;
        cats[2].stats.building = 80.0;

        let mut world = WorldState {
            world_seed: 123,
            colonies: vec![ColonyRuntime {
                id: "colony-1".to_owned(),
                name: "MossClan".to_owned(),
                leader_id: Some("leader".to_owned()),
                resources: Resources {
                    food: 30.0,
                    water: 1.0,
                    herbs: 16.0,
                    catnip: 0.0,
                    grain: 0.0,
                    flour: 0.0,
                    materials: 24.0,
                    refined: 0.0,
                    weapons: 0.0,
                    armor: 0.0,
                    planks: 0.0,
                    logs: 0.0,
                    lumber: 0.0,
                    blocks: 0.0,
                    tools: 0.0,
                    fibre: 0.0,
                    hide: 0.0,
                    cloth: 0.0,
                    leather: 0.0,
                    ore: 0.0,
                    metal: 0.0,
                    blessings: 0.0,
                },
                cats,
                buildings: vec![
                    BuildingRuntime {
                        id: "shrine".to_owned(),
                        building_type: BuildingType::Shrine,
                        level: 1,
                        position: pos(0, 0),
                        is_complete: true,
                        construction_progress: 100,
                        production_progress: 0.0,
                        assigned_cat: None,
                        automated_by: None,
                    },
                    BuildingRuntime {
                        id: "farmer-field".to_owned(),
                        building_type: BuildingType::Field,
                        level: 1,
                        position: pos(10, 10),
                        is_complete: true,
                        construction_progress: 100,
                        production_progress: 0.0,
                        assigned_cat: None,
                        automated_by: None,
                    },
                ],
                world_tiles: BTreeMap::from([(
                    pos(3, 0),
                    WorldTileRuntime {
                        pos: pos(3, 0),
                        tile_type: TileType::River,
                        resources: TileResources {
                            food: 0,
                            herbs: 0,
                            water: 100,
                        },
                        max_resources: MaxResources { food: 0, herbs: 0 },
                        danger_level: 0.0,
                        path_wear: 63,
                        last_depleted: 0,
                        overlay_feature: None,
                    },
                )]),
                revealed_tiles: BTreeSet::from([pos(3, 0)]),
                last_tick: 1_000,
                test_rng_seed: Some(12_345),
                ..ColonyRuntime::default()
            }],
        };

        world.colonies[0]
            .upgrade_tree
            .owned_node_ids
            .push("irrigation".to_owned());

        world.colonies[0]
            .officers
            .insert(OfficerRole::Farmer, "leader".to_owned());

        let _ = world_tick(&mut world, 61_000);

        let colony = &world.colonies[0];
        let water_jobs = colony
            .jobs
            .iter()
            .filter(|job| job.kind == JobKind::FetchWater)
            .collect::<Vec<_>>();
        assert_eq!(
            water_jobs.len(),
            2,
            "the Farmer keeps one real field worker while every remaining paw fetches water"
        );
        assert!(
            colony
                .jobs
                .iter()
                .all(|job| job.kind != JobKind::HuntExpedition)
        );
        let assigned = water_jobs
            .iter()
            .filter_map(|job| job.assigned_cat.as_deref())
            .collect::<BTreeSet<_>>();
        assert_eq!(assigned.len(), 2, "every non-field paw takes a water slot");
        assert!(water_jobs.iter().all(|job| {
            matches!(job.status, JobStatus::Queued | JobStatus::Active)
                && job.assigned_cat.is_some()
        }));
        let field_worker = colony
            .buildings
            .iter()
            .find(|building| building.id == "farmer-field")
            .and_then(|building| building.assigned_cat.as_deref())
            .expect("filled Farmer keeps the field staffed");
        assert!(!assigned.contains(field_worker));
        assert!(
            colony
                .cats
                .iter()
                .filter(|cat| cat.id != field_worker)
                .all(|cat| {
                    assigned.contains(cat.id.as_str())
                        && cat.current_task == Some(TaskType::FetchWater)
                })
        );
    }

