    #[test]
    fn logging_scan_groups_many_candidates_into_one_generation_per_chunk() {
        let mut colony = ColonyRuntime {
            anchor: pos(100, 100),
            ..ColonyRuntime::default()
        };
        for y in 0..crate::terrain_gen::TERRAIN_CHUNK_SIZE {
            for x in 0..crate::terrain_gen::TERRAIN_CHUNK_SIZE {
                let pos = TilePos { x, y };
                colony.world_tiles.insert(pos, tile(x, y, 63, None));
                colony.revealed_tiles.insert(pos);
            }
        }
        let (candidates, chunks) = logging_scan_inputs(&colony);
        assert_eq!(
            candidates.len(),
            (crate::terrain_gen::TERRAIN_CHUNK_SIZE * crate::terrain_gen::TERRAIN_CHUNK_SIZE)
                as usize
        );
        assert_eq!(chunks, BTreeSet::from([(0, 0)]));

        let next_chunk = TilePos {
            x: crate::terrain_gen::TERRAIN_CHUNK_SIZE,
            y: 0,
        };
        colony.world_tiles.insert(
            next_chunk,
            tile(crate::terrain_gen::TERRAIN_CHUNK_SIZE, 0, 63, None),
        );
        colony.revealed_tiles.insert(next_chunk);
        let (_, chunks) = logging_scan_inputs(&colony);
        assert_eq!(chunks, BTreeSet::from([(0, 0), (1, 0)]));
    }

    #[test]
    fn logging_selects_visible_generated_trees_only_outside_the_village_interior() {
        let (seed, anchor, interior, exterior) = (0_u32..10)
            .find_map(|seed| {
                let mut wood_trees = Vec::new();
                for chunk_y in -2..=2 {
                    for chunk_x in -2..=2 {
                        wood_trees.extend(
                            crate::terrain_gen::generate_terrain_chunk(
                                chunk_x,
                                chunk_y,
                                i64::from(seed),
                                crate::terrain_gen::WORLD_TERRAIN_OPTIONS,
                            )
                            .into_iter()
                            .filter(|tile| {
                                matches!(
                                    crate::terrain_gen::derive_biome_decoration(
                                        tile.x,
                                        tile.y,
                                        i64::from(seed),
                                        tile.climate_biome,
                                    ),
                                    Some(crate::terrain_gen::DecorationRole::Tree { .. })
                                )
                            })
                            .map(|tile| pos(tile.x, tile.y)),
                        );
                    }
                }
                wood_trees.iter().find_map(|&anchor| {
                    let exterior = wood_trees
                        .iter()
                        .copied()
                        .find(|tree| cheb_from_anchor(anchor, *tree) > VILLAGE_START_RADIUS)?;
                    Some((seed, anchor, anchor, exterior))
                })
            })
            .expect("bounded deterministic terrain contains interior and exterior wood trees");
        let mut colony = ColonyRuntime {
            anchor,
            ..ColonyRuntime::default()
        };
        colony
            .world_tiles
            .insert(interior, tile(interior.x, interior.y, 63, None));
        colony
            .world_tiles
            .insert(exterior, tile(exterior.x, exterior.y, 63, None));
        colony.revealed_tiles.extend([interior, exterior]);

        let sites = logging_sites_near_village(&colony, seed);
        assert_eq!(sites, vec![tile_pos_to_world(exterior)]);
        assert!(!sites.contains(&tile_pos_to_world(interior)));

        colony.resources.food = 100.0;
        colony.resources.water = 100.0;
        colony.cats = vec![
            adult_idle_cat("forester", "colony-1"),
            adult_idle_cat("spare", "colony-1"),
        ];
        colony.buildings.push(BuildingRuntime {
            id: "sawmill".to_owned(),
            building_type: BuildingType::Sawmill,
            level: 1,
            position: anchor,
            is_complete: true,
            construction_progress: 100,
            production_progress: 0.0,
            assigned_cat: None,
            automated_by: None,
        });
        colony
            .upgrade_tree
            .owned_node_ids
            .push("sawmill".to_owned());
        dispatch_officer_resource_jobs(&mut colony, 1_000, seed);
        assert!(colony.jobs.is_empty(), "vacant forestry remains manual");
        colony
            .officers
            .insert(OfficerRole::Forester, "forester".to_owned());
        dispatch_officer_resource_jobs(&mut colony, 1_001, seed);
        assert_eq!(colony.jobs.len(), 1);
        assert_eq!(colony.jobs[0].kind, JobKind::GatherLogs);
    }

    #[test]
    fn wood_cutter_refines_materials_into_planks_when_it_has_a_worker() {
        // Staffed: 590 + 30 ≥ 600 completes one cycle → 5 materials become 1 plank.
        let mut staffed = chain_colony(
            BuildingType::WoodCutter,
            Resources {
                materials: 50.0,
                ..Resources::default()
            },
            true,
        );
        phase_23_production(&mut staffed, production_gate(30, 30_000), 123);
        assert_eq!(staffed.resources.planks, 1.0);
        assert_eq!(staffed.resources.materials, 45.0);

        // A vacant Forester keeps the bench manual: an idle cat is not silently assigned.
        let mut manual = chain_colony(
            BuildingType::WoodCutter,
            Resources {
                materials: 50.0,
                ..Resources::default()
            },
            false,
        );
        phase_23_production(&mut manual, production_gate(30, 30_000), 123);
        assert_eq!(manual.resources.planks, 0.0);
        assert_eq!(manual.resources.materials, 50.0);

        // A living Forester owns raw-material-bench automation and staffs the same bench.
        let mut auto_staffed = chain_colony(
            BuildingType::WoodCutter,
            Resources {
                materials: 50.0,
                ..Resources::default()
            },
            false,
        );
        auto_staffed
            .officers
            .insert(OfficerRole::Forester, "crafter".to_owned());
        phase_23_production(&mut auto_staffed, production_gate(30, 30_000), 123);
        assert_eq!(auto_staffed.resources.planks, 1.0);
        assert_eq!(auto_staffed.resources.materials, 45.0);

        // With NO worker available at all (no cats to mop up), the bench still makes nothing.
        let mut no_worker = chain_colony(
            BuildingType::WoodCutter,
            Resources {
                materials: 50.0,
                ..Resources::default()
            },
            false,
        );
        no_worker.cats.clear();
        phase_23_production(&mut no_worker, production_gate(30, 30_000), 123);
        assert_eq!(no_worker.resources.planks, 0.0);
        assert_eq!(no_worker.resources.materials, 50.0);
    }

