    fn claim_and_connect_future_building_site(
        colony: &mut ColonyRuntime,
        seed: u32,
        building_type: BuildingType,
    ) -> TilePos {
        let site = next_expansion_building_site(colony, seed, building_type)
            .expect("a deterministic future building site exists");
        for tile in building_claim_region(site, building_type)
            .expect("the future site's claim margin is representable")
        {
            if !colony.claimed_tiles.contains(&tile) {
                colony.claimed_tiles.push(tile);
            }
            if tile_has_uncleared_tree(colony, tile, seed) {
                let mut cleared = fresh_ground_tile(tile);
                cleared.tile_type = TileType::Field;
                colony.world_tiles.insert(tile, cleared);
            }
        }
        let (width, height) = footprint_for(building_type);
        let reserved = footprint_tiles(site, width, height).into_iter().collect();
        assert!(connect_current_gate_to_shrine_avoiding(
            colony, seed, &reserved
        ));
        let access_route = candidate_building_road_route(colony, site, building_type, seed)
            .expect("claimed fixture site has a legal shrine access route");
        pave_access_route(colony, &access_route);
        site
    }

    #[test]
    fn breaking_ground_on_a_scaffold_consumes_planks_and_blocks() {
        // P19 slice 1b build cost: committing a scaffold site draws SCAFFOLD_PLANK_COST
        // planks + SCAFFOLD_BLOCK_COST blocks from the stores and places one new scaffold.
        let mut colony = found_colony(4242, "colony-1", 10_000, 4242);
        colony.resources.planks = 10.0;
        colony.resources.blocks = 10.0;
        let (timber_cost, block_cost) = scaffold_cost(&colony, BuildingType::Den);
        let cat_id = colony.cats[0].id.clone();
        let site = claim_and_connect_future_building_site(&mut colony, 4242, BuildingType::Den);
        let scaffolds_before = colony
            .buildings
            .iter()
            .filter(|building| !building.is_complete)
            .count();
        queue_job(
            &mut colony,
            10_000,
            JobKind::BuildHouse,
            Some(cat_id),
            JobMetadata::Construction {
                phase: ConstructionPhase::ConstructHouse,
                building_type: BuildingType::Den,
                building_id: None,
                site: Some(site),
            },
        );
        phase_14_promote_queued_jobs_and_break_ground(
            &mut colony,
            production_gate(60, 70_000),
            4242,
        );

        assert_eq!(colony.resources.planks, 10.0 - timber_cost);
        assert_eq!(colony.resources.blocks, 10.0 - block_cost);
        let scaffolds_after = colony
            .buildings
            .iter()
            .filter(|building| !building.is_complete)
            .count();
        assert_eq!(
            scaffolds_after,
            scaffolds_before + 1,
            "exactly one scaffold should have broken ground"
        );
        let scaffold = colony
            .buildings
            .iter()
            .find(|building| !building.is_complete)
            .expect("new scaffold exists");
        assert!(
            building_is_road_connected_to_shrine(&colony, scaffold, 4242),
            "break-ground commits the complete shrine access route atomically"
        );
        assert!(
            building_footprint_tiles(scaffold)
                .iter()
                .all(|tile| colony.claimed_tiles.contains(tile))
        );
    }

