    #[test]
    fn repeated_buildings_escalate_only_their_own_scaffold_cost_and_tools_respect_it() {
        let mut colony = ColonyRuntime::default();
        assert_eq!(scaffold_cost(&colony, BuildingType::Workshop), (2.0, 2.0));
        colony.buildings.push(BuildingRuntime {
            id: "workshop-1".to_owned(),
            building_type: BuildingType::Workshop,
            level: 1,
            position: TilePos { x: 1, y: 1 },
            is_complete: true,
            construction_progress: 100,
            production_progress: 0.0,
            assigned_cat: None,
            automated_by: None,
        });
        assert_eq!(scaffold_cost(&colony, BuildingType::Workshop), (2.5, 2.5));
        assert_eq!(
            scaffold_cost(&colony, BuildingType::Field),
            (2.0, 2.0),
            "a workshop does not inflate an unrelated field"
        );

        colony.jobs.push(JobRuntime {
            kind: JobKind::BuildHouse,
            status: JobStatus::Queued,
            metadata: JobMetadata::Construction {
                phase: ConstructionPhase::ConstructHouse,
                building_type: BuildingType::Workshop,
                building_id: None,
                site: None,
            },
            ..JobRuntime::default()
        });
        assert_eq!(construction_material_reserve(&colony), 4.0);

        for index in 2..=6 {
            colony.buildings.push(BuildingRuntime {
                id: format!("workshop-{index}"),
                building_type: BuildingType::Workshop,
                level: 1,
                position: TilePos { x: index, y: 1 },
                is_complete: true,
                construction_progress: 100,
                production_progress: 0.0,
                assigned_cat: None,
                automated_by: None,
            });
        }
        assert_eq!(scaffold_cost(&colony, BuildingType::Workshop), (5.0, 5.0));
        assert_eq!(
            construction_material_reserve(&colony),
            5.0,
            "the tools recipe protects the full pending repeat-build cost"
        );
    }

    #[test]
    fn unfinished_scaffold_is_reassigned_without_paying_break_ground_twice() {
        let mut colony = found_colony(4242, "colony-1", 10_000, 4242);
        colony.resources.planks = 10.0;
        colony.resources.blocks = 10.0;
        let first_builder = colony.cats[0].id.clone();
        let site =
            claim_and_connect_future_building_site(&mut colony, 4242, BuildingType::ResearchHut);
        queue_job(
            &mut colony,
            10_000,
            JobKind::BuildHouse,
            Some(first_builder.clone()),
            JobMetadata::Construction {
                phase: ConstructionPhase::ConstructHouse,
                building_type: BuildingType::ResearchHut,
                building_id: None,
                site: Some(site),
            },
        );
        phase_14_promote_queued_jobs_and_break_ground(
            &mut colony,
            production_gate(60, 70_000),
            4242,
        );
        let scaffold_id = colony
            .buildings
            .iter()
            .find(|building| building.building_type == BuildingType::ResearchHut)
            .expect("research scaffold")
            .id
            .clone();
        assert_eq!(
            (colony.resources.planks, colony.resources.blocks),
            (8.0, 8.0)
        );

        mark_cat_dead(&mut colony, &first_builder, 80_000);
        let buildings_before = colony.buildings.len();
        phase_14_promote_queued_jobs_and_break_ground(
            &mut colony,
            production_gate(60, 130_000),
            4242,
        );

        assert_eq!(colony.buildings.len(), buildings_before);
        assert_eq!(
            (colony.resources.planks, colony.resources.blocks),
            (8.0, 8.0),
            "resuming an existing scaffold must not charge the 2/2 site cost again"
        );
        assert!(colony.jobs.iter().any(|job| {
            job.status == JobStatus::Active
                && job.assigned_cat.as_deref() != Some(first_builder.as_str())
                && matches!(
                    &job.metadata,
                    JobMetadata::Construction {
                        building_id: Some(building_id),
                        ..
                    } if building_id == &scaffold_id
                )
        }));
    }

