    /// Attach a completed research hut, staffed by `scholar`, to `colony`.
    #[cfg(test)]
    fn attach_staffed_research_hut(colony: &mut ColonyRuntime, scholar: &str) {
        colony.buildings.push(BuildingRuntime {
            id: "research-hut-test".to_owned(),
            building_type: BuildingType::ResearchHut,
            level: 1,
            position: TilePos {
                x: colony.anchor.x,
                y: colony.anchor.y,
            },
            is_complete: true,
            construction_progress: 100,
            assigned_cat: Some(scholar.to_owned()),
            ..BuildingRuntime::default()
        });
    }

    /// A station is not truly occupied once its persisted worker id is dead or no longer
    /// exists in the roster. The autonomous staffing mop-up must replace either kind of
    /// stale assignment; otherwise a research hut can remain permanently dormant after its
    /// first scholar dies.
    #[test]
    fn auto_staff_replaces_dead_and_missing_building_assignees() {
        let mut colony = found_colony(7, "colony-1", 10_000, 7);
        colony.jobs.clear();
        let dead_scholar = colony.cats[0].id.clone();
        colony.cats[0].death_time = Some(10_001);
        attach_staffed_research_hut(&mut colony, &dead_scholar);

        auto_staff_idle_buildings(&mut colony, BuildingType::ResearchHut, 20_000, false);
        let replacement = assigned_worker(&colony, "research-hut-test")
            .expect("a living idle cat must replace a dead scholar")
            .id
            .clone();
        assert_ne!(replacement, dead_scholar);

        colony
            .buildings
            .iter_mut()
            .find(|building| building.id == "research-hut-test")
            .expect("research hut exists")
            .assigned_cat = Some("missing-cat".to_owned());
        auto_staff_idle_buildings(&mut colony, BuildingType::ResearchHut, 30_000, false);
        assert!(
            assigned_worker(&colony, "research-hut-test").is_some(),
            "a living idle cat must replace an assignee missing from the roster"
        );
    }

    #[test]
    fn interrupted_construction_keeps_its_scaffold_and_recruits_a_new_builder() {
        let seed = 7;
        let mut colony = found_colony(seed, "colony-1", 1_000, seed);
        colony.jobs.clear();
        let dead_builder = colony.cats[0].id.clone();
        colony.cats[0].needs = CatNeeds {
            hunger: 100.0,
            thirst: 0.0,
            rest: 100.0,
            health: 5.0,
        };
        colony.resources.water = 0.0;
        colony.buildings.push(BuildingRuntime {
            id: "paid-scaffold".to_owned(),
            building_type: BuildingType::ResearchHut,
            level: 1,
            position: TilePos { x: 0, y: 4 },
            is_complete: false,
            construction_progress: 73,
            production_progress: 0.0,
            assigned_cat: None,
            automated_by: None,
        });
        colony.jobs.push(JobRuntime {
            id: "interrupted-build".to_owned(),
            kind: JobKind::BuildHouse,
            status: JobStatus::Active,
            assigned_cat: Some(dead_builder.clone()),
            duration_ms: 60_000,
            started_at: Some(1_000),
            ends_at: Some(2_000),
            metadata: JobMetadata::Construction {
                phase: ConstructionPhase::ConstructHouse,
                building_type: BuildingType::ResearchHut,
                building_id: Some("paid-scaffold".to_owned()),
                site: Some(TilePos { x: 0, y: 4 }),
            },
            ..JobRuntime::default()
        });
        let death_gate = production_gate(1_200, 2_000);
        let building_count = colony.buildings.len();
        let planks = colony.resources.planks;
        let blocks = colony.resources.blocks;

        // Exercise the real survival-death cleanup. Ordinary work is cancelled
        // here, but paid construction must instead become resumable.
        phase_25_survival_deaths_and_carried_yield_salvage(
            &mut colony,
            death_gate,
            normal_policy(),
        );
        assert_eq!(
            colony.cats[0].death_time,
            Some(death_gate.processed_through)
        );
        let interrupted = colony
            .jobs
            .iter()
            .find(|job| job.id == "interrupted-build")
            .expect("the interrupted construction remains queued");
        assert_eq!(interrupted.status, JobStatus::Queued);
        assert!(interrupted.assigned_cat.is_none());
        assert_eq!(interrupted.started_at, None);
        assert_eq!(interrupted.ends_at, None);
        let scaffold = colony
            .buildings
            .iter()
            .find(|building| building.id == "paid-scaffold")
            .expect("the paid scaffold remains");
        assert!(!scaffold.is_complete);
        assert_eq!(scaffold.construction_progress, 73);
        assert_eq!(colony.buildings.len(), building_count);
        assert_eq!(colony.resources.planks.to_bits(), planks.to_bits());
        assert_eq!(colony.resources.blocks.to_bits(), blocks.to_bits());

        let resume_gate = production_gate(1, 3_000);
        phase_14_promote_queued_jobs_and_break_ground(&mut colony, resume_gate, seed);

        let restarted = colony
            .jobs
            .iter()
            .find(|job| job.id == "interrupted-build")
            .expect("the interrupted construction restarts");
        assert_eq!(restarted.status, JobStatus::Active);
        assert!(restarted.assigned_cat.as_deref().is_some_and(|cat_id| {
            cat_id != dead_builder
                && colony
                    .cats
                    .iter()
                    .any(|cat| cat.id == cat_id && cat.death_time.is_none())
        }));
        assert_eq!(restarted.started_at, Some(resume_gate.processed_through));
        assert_eq!(
            restarted.ends_at,
            Some(resume_gate.processed_through + 16_200),
            "73% complete means exactly 27% of the original timer remains"
        );
        assert_eq!(colony.buildings.len(), building_count);
        assert_eq!(colony.resources.planks.to_bits(), planks.to_bits());
        assert_eq!(colony.resources.blocks.to_bits(), blocks.to_bits());

        // Resuming cannot overwrite 73% with a fresh timer's 0%, and progress
        // continues from the stored baseline rather than restarting.
        phase_16_active_scaffold_progress(&mut colony, resume_gate);
        assert_eq!(
            colony
                .buildings
                .iter()
                .find(|building| building.id == "paid-scaffold")
                .expect("the scaffold remains while work resumes")
                .construction_progress,
            73
        );
        phase_16_active_scaffold_progress(&mut colony, production_gate(1, 11_100));
        assert_eq!(
            colony
                .buildings
                .iter()
                .find(|building| building.id == "paid-scaffold")
                .expect("the scaffold advances")
                .construction_progress,
            87
        );

        let completion_gate = production_gate(1, 19_200);
        phase_30_due_completion_build_ritual_training_return_mark_done(
            &mut colony,
            completion_gate,
        );
        let completed = colony
            .buildings
            .iter()
            .find(|building| building.id == "paid-scaffold")
            .expect("the recovered scaffold completes");
        assert!(completed.is_complete);
        assert_eq!(completed.construction_progress, 100);
        assert_eq!(
            colony
                .jobs
                .iter()
                .find(|job| job.id == "interrupted-build")
                .expect("the recovered build job completes")
                .status,
            JobStatus::Completed
        );
    }

    #[test]
    fn raid_death_requeues_a_paid_scaffold_instead_of_orphaning_it() {
        let mut colony = found_colony(7, "colony-1", 1_000, 7);
        colony.jobs.clear();
        let builder = colony.cats[0].id.clone();
        colony.buildings.push(BuildingRuntime {
            id: "raid-interrupted-scaffold".to_owned(),
            building_type: BuildingType::Workshop,
            level: 1,
            position: TilePos { x: 0, y: 4 },
            is_complete: false,
            construction_progress: 41,
            production_progress: 0.0,
            assigned_cat: None,
            automated_by: None,
        });
        colony.jobs.push(JobRuntime {
            id: "raid-interrupted-build".to_owned(),
            kind: JobKind::BuildHouse,
            status: JobStatus::Active,
            assigned_cat: Some(builder.clone()),
            duration_ms: 60_000,
            started_at: Some(1_000),
            ends_at: Some(61_000),
            metadata: JobMetadata::Construction {
                phase: ConstructionPhase::ConstructHouse,
                building_type: BuildingType::Workshop,
                building_id: Some("raid-interrupted-scaffold".to_owned()),
                site: Some(TilePos { x: 0, y: 4 }),
            },
            ..JobRuntime::default()
        });
        let planks = colony.resources.planks;
        let blocks = colony.resources.blocks;

        mark_cat_dead(&mut colony, &builder, 2_000);

        assert_eq!(colony.cats[0].death_time, Some(2_000));
        let job = colony
            .jobs
            .iter()
            .find(|job| job.id == "raid-interrupted-build")
            .expect("the paid build job survives its builder");
        assert_eq!(job.status, JobStatus::Queued);
        assert_eq!(job.assigned_cat, None);
        assert_eq!(job.started_at, None);
        assert_eq!(job.ends_at, None);
        assert_eq!(job.completed_at, None);
        let scaffold = colony
            .buildings
            .iter()
            .find(|building| building.id == "raid-interrupted-scaffold")
            .expect("the raid does not delete the paid scaffold");
        assert!(!scaffold.is_complete);
        assert_eq!(scaffold.construction_progress, 41);
        assert_eq!(colony.resources.planks.to_bits(), planks.to_bits());
        assert_eq!(colony.resources.blocks.to_bits(), blocks.to_bits());
    }

    /// Cat-research accrual wiring ([`research_workforce`] + [`phase_24_research`]). Before
    /// this fix `research_workforce` was hard-coded `0.0`, so a staffed hut banked nothing
    /// and the whole tech tree sat dormant in unattended play. A completed hut staffed by a
    /// living cat must now count as one researcher, and a game-week of accrual (20
    /// pts/researcher/week) must auto-unlock leader-priority nodes — proving the tree can
    /// advance on the cat path alone. Deterministic: a flat function of elapsed game-seconds,
    /// no RNG.
    #[test]
    fn staffed_research_hut_accrues_points_and_auto_unlocks_by_leader_priority() {
        let mut colony = found_colony(7, "colony-1", 10_000, 7);
        colony.upgrade_tree = crate::upgrade_tree::create_upgrade_tree_state();
        let scholar = colony.cats[0].id.clone();
        colony
            .officers
            .insert(OfficerRole::Loremaster, scholar.clone());

        // Unstaffed to start: the workforce is zero and no accrual happens.
        assert_eq!(
            research_workforce(&colony),
            0.0,
            "a colony with no staffed hut must yield zero research workforce"
        );

        attach_staffed_research_hut(&mut colony, &scholar);
        assert!(
            (research_workforce(&colony) - 1.0).abs() < 1e-9,
            "one living scholar in a completed hut is one researcher"
        );

        // One game-week banks ~20 points. The Loremaster completes exactly one
        // autonomous study now and leaves the rest for a later 24-hour interval.
        let week = crate::upgrade_tree::WEEK_SECONDS as i64;
        let gate = TickGate {
            elapsed_sec: week,
            processed_through: colony.last_tick + week * 1_000,
            minute_rolled: true,
            previous_water: colony.resources.water.to_bits(),
        };
        phase_24_research(&mut colony, gate);

        assert!(
            colony
                .upgrade_tree
                .owned_node_ids
                .contains(&"research_hut".to_owned()),
            "a game-week of research must unlock the cost-5 root node, got {:?}",
            colony.upgrade_tree.owned_node_ids,
        );
        assert_eq!(colony.upgrade_tree.owned_node_ids, ["research_hut"]);
        assert_eq!(
            colony.last_loremaster_unlock_at,
            Some(gate.processed_through)
        );
        assert!((colony.upgrade_tree.research_points - 15.0).abs() < 1e-9);

        // Unstaffing the hut drops the workforce back to zero (dead/absent scholar guard).
        for building in &mut colony.buildings {
            if building.building_type == BuildingType::ResearchHut {
                building.assigned_cat = None;
            }
        }
        assert_eq!(research_workforce(&colony), 0.0);
    }

    #[test]
    fn loremaster_unlocks_at_most_one_node_per_rolling_day_at_the_exact_boundary() {
        let mut colony = found_colony(7, "colony-1", 10_000, 7);
        establish_office(&mut colony, OfficerRole::Loremaster);
        let starting_owned = colony.upgrade_tree.owned_node_ids.len();
        let first_at = 100_000;

        phase_24_research(&mut colony, production_gate(1, first_at - 1));
        assert_eq!(colony.last_loremaster_unlock_at, None);
        assert_eq!(colony.upgrade_tree.owned_node_ids.len(), starting_owned);

        colony.upgrade_tree.research_points = 100.0;

        phase_24_research(&mut colony, production_gate(1, first_at));
        assert_eq!(colony.upgrade_tree.owned_node_ids.len(), starting_owned + 1);
        assert_eq!(colony.last_loremaster_unlock_at, Some(first_at));

        phase_24_research(
            &mut colony,
            production_gate(1, first_at + LOREMASTER_UNLOCK_INTERVAL_MS - 1),
        );
        assert_eq!(
            colony.upgrade_tree.owned_node_ids.len(),
            starting_owned + 1,
            "sub-day tick must not spend another node"
        );

        phase_24_research(
            &mut colony,
            production_gate(1, first_at + LOREMASTER_UNLOCK_INTERVAL_MS),
        );
        assert_eq!(
            colony.upgrade_tree.owned_node_ids.len(),
            starting_owned + 2,
            "the exact 24h boundary admits one further node"
        );

        phase_24_research(&mut colony, production_gate(1, first_at - 1));
        assert_eq!(
            colony.upgrade_tree.owned_node_ids.len(),
            starting_owned + 2,
            "clock rollback must not reopen an already-consumed day"
        );

        phase_24_research(
            &mut colony,
            production_gate(1, first_at + 5 * LOREMASTER_UNLOCK_INTERVAL_MS),
        );
        assert_eq!(
            colony.upgrade_tree.owned_node_ids.len(),
            starting_owned + 3,
            "a multi-day offline jump grants one current-day unlock, not backlog"
        );
    }

    #[test]
    fn loremaster_daily_unlock_sequence_is_deterministic() {
        let run = || {
            let mut colony = found_colony(42, "colony-1", 10_000, 42);
            establish_office(&mut colony, OfficerRole::Loremaster);
            colony.upgrade_tree.research_points = 100.0;
            for day in 0..4 {
                phase_24_research(
                    &mut colony,
                    production_gate(1, 100_000 + day * LOREMASTER_UNLOCK_INTERVAL_MS),
                );
            }
            (
                colony.upgrade_tree,
                colony.last_loremaster_unlock_at,
                colony.events,
            )
        };
        assert_eq!(run(), run());
    }

    /// Survival guardrail for the cat-research path: staffing a research hut must respect the
    /// comfort gate the `AssignResearch` labour goal already carries, so a *starving* colony
    /// never pulls a mouth off survival work to study. A completed, unstaffed hut in a colony
    /// held below the [`is_research_comfortable`] per-capita bar on food/water stays unstaffed
    /// and commissions no new hut; the same colony made comfortable staffs it. Deterministic
    /// (short bounded run).
    #[test]
    fn research_staffing_and_commission_respect_the_comfort_gate() {
        // Starving: food/water pinned near zero every tick, so no comfortable ticks pass.
        // Both halves age the run past the research establishment window so the assert
        // exercises the comfort gate itself, not the founding-window guard.
        let mut world = new_world(7);
        let mut colony = found_colony(world.world_seed, "colony-1", 10_000, 7);
        colony.run_started_at = 10_000 - RESEARCH_ESTABLISHMENT_MS;
        establish_office(&mut colony, OfficerRole::Loremaster);
        let scholar = colony.officers[&OfficerRole::Loremaster].clone();
        for building in &mut colony.buildings {
            if building.building_type == BuildingType::ResearchHut {
                building.assigned_cat = Some(scholar.clone());
            }
        }
        // Free the scholar so only the leader (comfort-gated) could re-staff it.
        for building in &mut colony.buildings {
            if building.building_type == BuildingType::ResearchHut {
                building.assigned_cat = None;
            }
        }
        world.colonies.push(colony);
        for step in 1..=20 {
            // Re-starve before each tick so the colony can never read as comfortable.
            let c = &mut world.colonies[0];
            c.resources.food = 1.0;
            c.resources.water = 1.0;
            let now = 10_000 + i64::from(step) * 60_000;
            let _ = world_tick(&mut world, now);
            assert_eq!(
                research_workforce(&world.colonies[0]),
                0.0,
                "tick {step}: a starving colony must not staff its research hut",
            );
        }
        assert!(
            world.colonies[0]
                .buildings
                .iter()
                .filter(|b| b.building_type == BuildingType::ResearchHut)
                .count()
                == 1,
            "a starving colony must not commission a second research hut",
        );

        // Comfortable: food/water pinned at capacity, so the leader staffs the idle hut.
        let mut comfy = new_world(7);
        let mut colony = found_colony(comfy.world_seed, "colony-1", 10_000, 7);
        colony.run_started_at = 10_000 - RESEARCH_ESTABLISHMENT_MS;
        establish_office(&mut colony, OfficerRole::Loremaster);
        let scholar = colony.officers[&OfficerRole::Loremaster].clone();
        for building in &mut colony.buildings {
            if building.building_type == BuildingType::ResearchHut {
                building.assigned_cat = Some(scholar.clone());
            }
        }
        for building in &mut colony.buildings {
            if building.building_type == BuildingType::ResearchHut {
                building.assigned_cat = None;
            }
        }
        comfy.colonies.push(colony);
        let mut staffed = false;
        for step in 1..=40 {
            let c = &mut comfy.colonies[0];
            let caps = storage_caps(c);
            c.resources.food = caps.food;
            c.resources.water = caps.water;
            let now = 10_000 + i64::from(step) * 60_000;
            let _ = world_tick(&mut comfy, now);
            if research_workforce(&comfy.colonies[0]) > 0.0 {
                staffed = true;
                break;
            }
        }
        assert!(
            staffed,
            "a comfortable colony must staff its idle research hut within a few ticks",
        );
    }

    #[test]
    fn low_comfort_releases_only_loremaster_owned_scholars() {
        let mut colony = found_colony(7, "colony-1", 10_000, 7);
        colony.resources.food = 1.0;
        colony.resources.water = 1.0;
        let automated_scholar = colony.cats[0].id.clone();
        let manual_scholar = colony.cats[1].id.clone();
        attach_staffed_research_hut(&mut colony, &automated_scholar);
        let automated = colony
            .buildings
            .iter_mut()
            .find(|building| building.id == "research-hut-test")
            .expect("automated research hut exists");
        automated.automated_by = Some(OfficerRole::Loremaster);
        attach_staffed_school(&mut colony, &manual_scholar);

        let snapshot = phase_18_leader_snapshot_assembly(&mut colony, production_gate(1, 70_000));
        assert!(!is_research_comfortable(&snapshot));
        release_research_staff_unless_comfortable(&mut colony, &snapshot);

        let automated = colony
            .buildings
            .iter()
            .find(|building| building.id == "research-hut-test")
            .expect("automated research hut remains");
        assert_eq!(automated.assigned_cat, None);
        assert_eq!(automated.automated_by, None);
        let manual = colony
            .buildings
            .iter()
            .find(|building| building.id == "school-test")
            .expect("manual school remains");
        assert_eq!(
            manual.assigned_cat.as_deref(),
            Some(manual_scholar.as_str())
        );
        assert_eq!(manual.automated_by, None);
    }

    /// Attach a completed school, staffed by `scholar`, to `colony`.
    #[cfg(test)]
    fn attach_staffed_school(colony: &mut ColonyRuntime, scholar: &str) {
        colony.buildings.push(BuildingRuntime {
            id: "school-test".to_owned(),
            building_type: BuildingType::School,
            level: 1,
            position: TilePos {
                x: colony.anchor.x,
                y: colony.anchor.y,
            },
            is_complete: true,
            construction_progress: 100,
            assigned_cat: Some(scholar.to_owned()),
            ..BuildingRuntime::default()
        });
    }

    /// The school is a second staffed research building (unlocked by the "school" upgrade
    /// node): a completed, staffed school must count toward [`research_workforce`] exactly
    /// like a research hut, and the two stack — a colony with one of each fields two
    /// researchers. Mirrors
    /// [`staffed_research_hut_accrues_points_and_auto_unlocks_by_leader_priority`], swapping
    /// the hut for a school (and covering the stacked case the hut-only test doesn't).
    #[test]
    fn staffed_school_contributes_research_workforce_and_accrues_points() {
        let mut colony = found_colony(7, "colony-1", 10_000, 7);
        colony.upgrade_tree = crate::upgrade_tree::create_upgrade_tree_state();
        let scholar = colony.cats[0].id.clone();
        colony
            .officers
            .insert(OfficerRole::Loremaster, scholar.clone());

        assert_eq!(
            research_workforce(&colony),
            0.0,
            "a colony with no staffed research building must yield zero research workforce"
        );

        attach_staffed_school(&mut colony, &scholar);
        assert!(
            (research_workforce(&colony) - 1.0).abs() < 1e-9,
            "one living scholar in a completed school is one researcher"
        );

        // A research hut staffed by a second scholar stacks on top of the school.
        let second_scholar = colony.cats[1].id.clone();
        attach_staffed_research_hut(&mut colony, &second_scholar);
        assert!(
            (research_workforce(&colony) - 2.0).abs() < 1e-9,
            "a staffed school and a staffed research hut must both contribute workforce"
        );

        // One game-week of two researchers banks ~20 points, comfortably auto-unlocking the
        // cost-5 root node (`research_hut`) and beyond.
        let week = crate::upgrade_tree::WEEK_SECONDS as i64;
        let gate = TickGate {
            elapsed_sec: week,
            processed_through: colony.last_tick + week * 1_000,
            minute_rolled: true,
            previous_water: colony.resources.water.to_bits(),
        };
        phase_24_research(&mut colony, gate);

        assert!(
            colony
                .upgrade_tree
                .owned_node_ids
                .contains(&"research_hut".to_owned()),
            "a game-week of research from a staffed school must unlock the cost-5 root node, \
             got {:?}",
            colony.upgrade_tree.owned_node_ids,
        );

        // Unstaffing the school (but leaving the hut staffed) drops the workforce by exactly
        // one — the dead/absent scholar guard applies per-building, not colony-wide.
        for building in &mut colony.buildings {
            if building.building_type == BuildingType::School {
                building.assigned_cat = None;
            }
        }
        assert!(
            (research_workforce(&colony) - 1.0).abs() < 1e-9,
            "unstaffing the school must leave only the research hut's researcher"
        );
    }

    /// Live-cadence player-guided founding water guardrail.
    ///
    /// A fresh village has no legal Farmer yet, so its water work is deliberately manual.
    /// This drives the typed `RequestJob(FetchWater)` simulation action at the true one-second
    /// cadence with default decay, proving the player-guided founding loop discovers a real
    /// source, travels, hauls, deposits, and recovers a deliberately lean reservoir. Authenticated
    /// WebSocket routing is covered separately by the server campaign.
    #[test]
    fn player_guided_founding_water_fetch_runs_at_the_live_one_second_cadence() {
        for seed in [1234u32, 42, 7] {
            let mut world = new_world(seed);
            let mut colony = found_colony(world.world_seed, "colony-1", 10_000, seed);
            // Lean founding reservoir so the water-standup crisis is reached in a bounded tick
            // budget; everything else (food, decay, time scale) stays at the live default.
            colony.resources.water = 10.0;
            reconcile_colony_stockpiles(&mut colony);
            world.colonies.push(colony);
            let pre_action_water = world.colonies[0].resources.water;

            let action = proto::ClientAction::RequestJob {
                session_id: "founding-water-session".to_owned(),
                nickname: "Water guide".to_owned(),
                sig: "pure-sim".to_owned(),
                kind: proto::JobKind::FetchWater,
            };
            let result = apply_action(
                &mut world,
                &action,
                &ActionCtx {
                    session_id: "founding-water-session".to_owned(),
                    player_id: "founding-water-player".to_owned(),
                    colony_id: "colony-1".to_owned(),
                    now_ms: 10_001,
                },
            );
            assert!(
                result.ok,
                "seed {seed}: manual founding FetchWater failed: {:?}",
                result.message
            );
            assert_eq!(
                world.colonies[0].resources.water.to_bits(),
                pre_action_water.to_bits(),
                "requesting work never credits free water"
            );
            let player_job = world.colonies[0]
                .jobs
                .iter()
                .find(|job| {
                    job.kind == JobKind::FetchWater && job.requested_by == JobRequester::Player
                })
                .expect("the typed player action creates one player-owned fetch");
            let player_job_id = player_job.id.clone();
            let player_cat_id = player_job
                .assigned_cat
                .clone()
                .expect("the manual fetch has a real worker");
            assert!(matches!(
                player_job.status,
                JobStatus::Queued | JobStatus::Active
            ));
            assert!(player_job.duration_ms > 0);
            assert!(player_job.started_at.is_some());
            assert!(
                player_job
                    .ends_at
                    .is_some_and(|ends_at| ends_at > player_job.created_at)
            );

            let starting_water = world.colonies[0].resources.water;
            let mut water_max = starting_water;
            let mut previous_water = starting_water;
            let mut observed_site = None;
            let mut saw_worker_at_site = false;
            let mut saw_returning_water = false;
            let mut saw_water_deposit = false;
            let mut previous_had_water_cargo = false;
            let mut min_population = usize::MAX;
            for step in 1..=3_000i64 {
                let now = 10_000 + step * 1_000; // 1 s live cadence, default time scale
                let reports = world_tick(&mut world, now);
                let colony = &world.colonies[0];

                assert_eq!(
                    reports[0].reset_reason, None,
                    "seed {seed} tick {step}: founding colony reset ({:?}) — the water loop never stood up",
                    reports[0].reset_reason,
                );

                let exact_job = colony
                    .jobs
                    .iter()
                    .find(|job| job.id == player_job_id)
                    .expect("the player fetch remains in the retained job history");
                if let JobMetadata::Hauling {
                    site: Some(site), ..
                } = exact_job.metadata
                {
                    let tile = colony
                        .world_tiles
                        .get(&site)
                        .expect("the assigned water source exists");
                    assert!(tile_has_water(Some(tile)));
                    assert!(tile_is_explored(colony, tile));
                    observed_site = Some(site);
                }
                let worker = colony
                    .cats
                    .iter()
                    .find(|cat| cat.id == player_cat_id)
                    .expect("the assigned water carrier remains in the roster");
                let has_water_cargo = worker
                    .carrying
                    .as_ref()
                    .is_some_and(|cargo| cargo.kind == CarryingKind::Water && cargo.amount > 0.0);
                if let Some(site) = observed_site {
                    saw_worker_at_site |=
                        world_pos_to_tile(position_to_world(colony.anchor, worker.position))
                            == site
                            && (worker.activity == CatActivity::Working || has_water_cargo);
                }
                saw_returning_water |= worker.activity == CatActivity::Returning
                    && worker.carrying.as_ref().is_some_and(|cargo| {
                        cargo.kind == CarryingKind::Water && cargo.amount > 0.0
                    });
                saw_water_deposit |= previous_had_water_cargo
                    && !has_water_cargo
                    && colony.resources.water > previous_water;
                previous_had_water_cargo = has_water_cargo;
                previous_water = colony.resources.water;
                water_max = water_max.max(colony.resources.water);
                min_population = min_population.min(alive_cats(&colony.cats).count());
            }

            let colony = &world.colonies[0];
            assert_ne!(
                colony.status,
                ColonyStatus::Dead,
                "seed {seed}: colony died"
            );
            assert!(
                observed_site.is_some(),
                "seed {seed}: the player fetch never resolved a physical source"
            );
            assert!(
                saw_worker_at_site,
                "seed {seed}: the assigned player cat never reached its water source"
            );
            assert!(
                saw_returning_water,
                "seed {seed}: no water carrier entered the return leg"
            );
            assert!(
                saw_water_deposit,
                "seed {seed}: the returning cargo never increased stored water"
            );
            // A novice carrier receives the 0.75 skill floor (30 from the 40-unit
            // base yield). With the 15-cat founding roster, several more units are
            // consumed during the physical outbound/work/return trip, so require a
            // clear net recovery without pretending the gross base yield is banked.
            assert!(
                water_max >= starting_water + WATER_TOTAL_YIELD * 0.6,
                "seed {seed}: water never recovered (peaked at {water_max:.1}) — the fetch loop is not delivering"
            );
            assert!(
                colony.resources.water > starting_water,
                "seed {seed}: water ended at {:.1}, no better than the lean start — the loop is bleeding, not standing up",
                colony.resources.water,
            );
            assert!(
                min_population >= STARTER_CAT_COUNT,
                "seed {seed}: population dipped to {min_population} — a cat died during founding standup"
            );
        }
    }

    // ---- Phase 25: survival needs, dehydration/starvation death, carried-yield salvage ----

    /// A minimal single-cat colony for phase-25 unit tests — no buildings/stockpiles
    /// needed since `credit_carrying` degrades gracefully to crediting `resources`
    /// directly when no designated pile exists (mirrors the no-pile hauling tests).
    fn survival_colony(cat: Cat, food: f64, water: f64) -> ColonyRuntime {
        ColonyRuntime {
            id: "colony-1".to_owned(),
            resources: Resources {
                food,
                water,
                ..Resources::default()
            },
            cats: vec![cat],
            ..ColonyRuntime::default()
        }
    }

    fn survival_cat(needs: CatNeeds) -> Cat {
        Cat {
            needs,
            ..adult_idle_cat("cat-1", "colony-1")
        }
    }

    fn normal_policy() -> TickPolicy {
        TickPolicy {
            config: crate::policy::config_for_tier(crate::types::PolicyTier::Normal),
        }
    }

    #[test]
    fn water_depletion_crisis_starts_before_death() {
        // Water fully depleted, food plentiful: thirst decays at the full (water-
        // unavailable) rate and crosses zero this tick, but the single tick's damage
        // isn't enough to kill — the cat is in crisis, not dead.
        let cat = survival_cat(CatNeeds {
            hunger: 100.0,
            thirst: 1.0,
            rest: 100.0,
            health: 100.0,
        });
        let mut colony = survival_colony(cat, 100.0, 0.0);

        phase_25_survival_deaths_and_carried_yield_salvage(
            &mut colony,
            production_gate(600, 600_000),
            normal_policy(),
        );

        assert_eq!(colony.cats[0].needs.thirst, 0.0);
        assert!(colony.cats[0].needs.health > 0.0);
        assert_eq!(colony.cats[0].death_time, None);
        assert!(
            colony.events.iter().any(|event| {
                event.kind == EventKind::DehydrationCrisis
                    && event.message == "Poppy started dehydrating."
            }),
            "expected a dehydration crisis event, got {:?}",
            colony.events
        );
    }

    #[test]
    fn dehydration_death_past_the_threshold_logs_a_death_event() {
        // Already dehydrating (thirst pinned at 0, water still out) with low health —
        // this tick's damage finishes the job.
        let cat = survival_cat(CatNeeds {
            hunger: 100.0,
            thirst: 0.0,
            rest: 100.0,
            health: 20.0,
        });
        let mut colony = survival_colony(cat, 100.0, 0.0);

        phase_25_survival_deaths_and_carried_yield_salvage(
            &mut colony,
            production_gate(4_200, 4_200_000),
            normal_policy(),
        );

        assert_eq!(colony.cats[0].needs.health, 0.0);
        assert_eq!(colony.cats[0].death_time, Some(4_200_000));
        assert_eq!(colony.cats[0].activity, CatActivity::Idle);
        assert_eq!(colony.cats[0].destination, None);
        assert_eq!(colony.cats[0].carrying, None);
        assert!(
            colony.events.iter().any(|event| event.kind
                == EventKind::Death(DeathCause::Dehydration)
                && event.message == "Poppy died from dehydration."),
            "expected a dehydration death event, got {:?}",
            colony.events
        );
    }

    #[test]
    fn water_restoration_recovers_before_the_death_threshold() {
        // Thirst is pinned at 0 (already dehydrating) but water is restored this tick —
        // the counter should reset upward and the cat survives.
        let cat = survival_cat(CatNeeds {
            hunger: 100.0,
            thirst: 0.0,
            rest: 100.0,
            health: 50.0,
        });
        let mut colony = survival_colony(cat, 100.0, 10.0);

        phase_25_survival_deaths_and_carried_yield_salvage(
            &mut colony,
            production_gate(600, 600_000),
            normal_policy(),
        );

        assert!(colony.cats[0].needs.thirst > 0.0);
        assert_eq!(colony.cats[0].needs.health, 50.0);
        assert_eq!(colony.cats[0].death_time, None);
        assert!(
            colony.events.iter().any(|event| {
                event.kind == EventKind::DehydrationRecovery
                    && event.message == "Poppy recovered from dehydration."
            }),
            "expected a dehydration recovery event, got {:?}",
            colony.events
        );
    }

    #[test]
    fn starvation_death_past_the_threshold_logs_a_starvation_event() {
        // Food fully depleted (water fine), hunger already pinned at 0 with low
        // health — this tick's damage kills, and the cause reads "starvation", not
        // "dehydration" (mirrors `server/game.ts`'s cause-string branching).
        let cat = survival_cat(CatNeeds {
            hunger: 0.0,
            thirst: 100.0,
            rest: 100.0,
            health: 10.0,
        });
        let mut colony = survival_colony(cat, 0.0, 100.0);

        phase_25_survival_deaths_and_carried_yield_salvage(
            &mut colony,
            production_gate(1_200, 1_200_000),
            normal_policy(),
        );

        assert_eq!(colony.cats[0].needs.health, 0.0);
        assert_eq!(colony.cats[0].death_time, Some(1_200_000));
        assert!(
            colony.events.iter().any(|event| event.kind
                == EventKind::Death(DeathCause::Starvation)
                && event.message == "Poppy died from starvation."),
            "expected a starvation death event, got {:?}",
            colony.events
        );
    }

    #[test]
    fn dying_carriers_yield_is_salvaged_into_the_store_and_carrying_is_cleared() {
        let mut cat = survival_cat(CatNeeds {
            hunger: 100.0,
            thirst: 0.0,
            rest: 100.0,
            health: 5.0,
        });
        cat.carrying = Some(Carrying {
            kind: CarryingKind::Materials,
            amount: 12.0,
            job_ended_at: 0,
            source_gather_spot: None,
        });
        let mut colony = survival_colony(cat, 100.0, 0.0);
        colony.resources.materials = 5.0;

        phase_25_survival_deaths_and_carried_yield_salvage(
            &mut colony,
            production_gate(1_200, 1_200_000),
            normal_policy(),
        );

        assert_eq!(colony.cats[0].death_time, Some(1_200_000));
        assert_eq!(colony.cats[0].carrying, None);
        assert_eq!(colony.resources.materials, 17.0);
    }

    #[test]
    fn dying_cats_active_and_queued_jobs_are_cancelled() {
        let cat = survival_cat(CatNeeds {
            hunger: 100.0,
            thirst: 0.0,
            rest: 100.0,
            health: 5.0,
        });
        let mut colony = survival_colony(cat, 100.0, 0.0);
        colony.jobs = vec![
            JobRuntime {
                id: "job-active".to_owned(),
                kind: JobKind::HuntExpedition,
                status: JobStatus::Active,
                requested_by: JobRequester::Leader,
                assigned_cat: Some("cat-1".to_owned()),
                duration_ms: 1_000,
                speed: 1.0,
                yield_amount: 0.0,
                click_count: 0,
                created_at: 0,
                started_at: Some(0),
                ends_at: Some(999_999_999),
                completed_at: None,
                metadata: JobMetadata::None,
            },
            JobRuntime {
                id: "job-queued".to_owned(),
                kind: JobKind::Quarry,
                status: JobStatus::Queued,
                requested_by: JobRequester::Leader,
                assigned_cat: Some("cat-1".to_owned()),
                duration_ms: 1_000,
                speed: 1.0,
                yield_amount: 0.0,
                click_count: 0,
                created_at: 0,
                started_at: None,
                ends_at: None,
                completed_at: None,
                metadata: JobMetadata::None,
            },
        ];

        phase_25_survival_deaths_and_carried_yield_salvage(
            &mut colony,
            production_gate(1_200, 1_200_000),
            normal_policy(),
        );

        assert_eq!(colony.cats[0].death_time, Some(1_200_000));
        assert!(
            colony
                .jobs
                .iter()
                .all(|job| job.status == JobStatus::Cancelled),
            "expected both jobs cancelled, got {:?}",
            colony.jobs
        );
    }

    #[test]
    fn survival_tick_is_deterministic_across_identical_runs_through_a_depletion() {
        // Two independently-founded worlds on the same seed, driven through the same
        // forced water depletion (a direct, non-RNG mutation applied identically to
        // both), must end up byte-identical — including the eventual dehydration
        // death. Proves phase 25's deterministic-threshold model (no RNG chain to
        // desync) stays byte-identical under a real depletion + death event.
        let mut left = new_world(4242);
        left.colonies
            .push(found_colony(left.world_seed, "colony-1", 10_000, 4242));
        let mut right = new_world(4242);
        right
            .colonies
            .push(found_colony(right.world_seed, "colony-1", 10_000, 4242));

        // This fixture is specifically a no-supply depletion. A normal founding
        // village has a guaranteed spring and dispatches a physical water carrier,
        // so remove every water tile from both twins before forcing the reservoir dry.
        for world in [&mut left, &mut right] {
            let water_tiles = world.colonies[0]
                .world_tiles
                .iter()
                .filter_map(|(pos, tile)| tile_has_water(Some(tile)).then_some(*pos))
                .collect::<Vec<_>>();
            for pos in water_tiles {
                clear_water_tile(&mut world.colonies[0], pos);
            }
            assert!(!has_water_site(&world.colonies[0]));
        }

        // Force one cat toward the dehydration-death edge identically on both worlds
        // — a plain field write, not RNG, so it cannot desync the twin.
        let starved_needs = CatNeeds {
            hunger: 100.0,
            thirst: 1.0,
            rest: 100.0,
            health: 0.5,
        };
        left.colonies[0].cats[0].needs = starved_needs.clone();
        right.colonies[0].cats[0].needs = starved_needs;

        for step in 1..=40 {
            let now = 10_000 + i64::from(step) * 60_000;
            // Keep water at zero throughout so the depletion is sustained regardless
            // of any leader fetch-water response, identically on both worlds.
            left.colonies[0].resources.water = 0.0;
            right.colonies[0].resources.water = 0.0;
            assert_eq!(world_tick(&mut left, now), world_tick(&mut right, now));
        }

        assert_eq!(left.colonies[0].cats, right.colonies[0].cats);
        assert!(
            left.colonies[0].cats[0].death_time.is_some(),
            "the forced depletion never actually killed the cat — twin comparison is vacuous"
        );
        assert!(
            left.colonies[0]
                .events
                .iter()
                .any(|event| event.message.contains("died from")),
            "expected a death event on both worlds, got {:?}",
            left.colonies[0].events
        );
    }

    // ---- Phase 6 pass 1: old-age death parity with phase 25 survival deaths ----

    /// A cat old enough that, after phase 6's per-tick age increment, the
    /// `hoursPastThreshold` term alone drives `old_age_death_probability` to its 1.0
    /// clamp for any positive elapsed window — deterministic old-age death regardless
    /// of the RNG roll (reached here via extreme age rather than extreme elapsed
    /// hours, unlike `life_sim::old_age_death_probability_scales_and_clamps`'s
    /// "skip-time cap" case, but the same clamp).
    fn ancient_cat(id: &str, colony_id: &str) -> Cat {
        Cat {
            age_hours: 100_000.0,
            ..adult_idle_cat(id, colony_id)
        }
    }

